{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — A calibrated path to resilient balance</title>
  <meta name='description' content='Holistic approaches blending roots of science, ritual, and everyday routines to steady real lives.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body class='page-hero'>
  <header class='site-header'>
    <div class='wrap header-grid'>
      <a class='brand' href='index.html' aria-label='Home'>
        <svg class='logo' width='44' height='44' viewBox='0 0 44 44' role='img' aria-hidden='true'>
          <circle cx='22' cy='22' r='20' fill='none' stroke='currentColor' stroke-width='2'/>
          <path d='M11 28 L22 15 L33 28' stroke='currentColor' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/>
        </svg>
        <span class='brand-name'>{{BUSINESS_NAME}}</span>
      </a>
      <nav class='nav' aria-label='Primary navigation'>
        <a href='services.html'>Programs</a>
        <a href='conditions.html'>Conditions</a>
        <a href='approach.html'>Philosophy</a>
        <a href='pricing.html'>Invest</a>
        <a href='about.html'>About</a>
        <a href='book.html' class='book-link'>Book</a>
        <a href='contact.html' class='connect-link'>Connect</a>
      </nav>
      <div class='nav-cta'>
        <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
  </header>

  <main>
    <section class='hero wrap'>
      <div class='hero-grid'>
        <div class='hero-copy'>
          <h1 class='eyebrow'>A quieter architecture for well-being</h1>
          <p class='lead'>We map signals across sleep, digestion, mood and breath into an approachable plan that fits your rhythms—not the other way around. {{TAGLINE}}</p>
          <div class='hero-actions'>
            <a class='btn primary large' href='{{PRIMARY_CTA_URL}}'>Begin a guided plan</a>
            <a class='btn ghost' href='about.html'>Meet the team</a>
          </div>
          <ul class='hero-stats' aria-hidden='true'>
            <li><strong>4–12</strong><span>week pathways</span></li>
            <li><strong>Clinician-led</strong><span>and home-friendly</span></li>
            <li><strong>Evidence-forward</strong><span>with lived wisdom</span></li>
          </ul>
        </div>
        <div class='hero-aside'>
          <div class='pattern-plate' role='img' aria-label='Decorative pattern'>
            <svg class='plate' viewBox='0 0 400 300' preserveAspectRatio='xMidYMid slice'>
              <rect width='100%' height='100%' fill='url(#p)' />
              <defs>
                <pattern id='p' x='0' y='0' width='40' height='40' patternUnits='userSpaceOnUse'>
                  <rect x='0' y='0' width='40' height='40' fill='#fff0' />
                  <circle cx='20' cy='20' r='6' fill='rgba(70,120,110,0.06)' />
                  <path d='M0 40 L40 0' stroke='rgba(70,120,110,0.04)' stroke-width='2'/>
                </pattern>
              </defs>
            </svg>
          </div>
        </div>
      </div>
    </section>

    <section class='myth-truth wrap' aria-labelledby='myth-title'>
      <h2 id='myth-title'>Common assumptions — and a different view</h2>
      <div class='myth-grid'>
        <article>
          <h3>Myth</h3>
          <p>There is a single treatment path that fixes everything.</p>
        </article>
        <article>
          <h3>Reality</h3>
          <p>Small, targeted shifts across systems often offer more durable change than large, singular interventions. We layer practices using context-sensitive tests and lived experience.</p>
        </article>
        <article>
          <h3>Myth</h3>
          <p>Healing is linear and rapid.</p>
        </article>
        <article>
          <h3>Reality</h3>
          <p>Progress rarely moves in a straight line. Our plans include checkpoints and adaptions so you can keep moving forward with clarity.</p>
        </article>
      </div>
    </section>

    <section class='pillars wrap' aria-labelledby='pillars-title'>
      <h2 id='pillars-title'>A four-lane approach</h2>
      <div class='pillars-grid'>
        <div class='pillar'>
          <h3>Structure</h3>
          <p>Simple routines that anchor your day without friction.</p>
        </div>
        <div class='pillar'>
          <h3>Signals</h3>
          <p>Targeted measures to reveal patterns across sleep, digestion, mood and energy.</p>
        </div>
        <div class='pillar'>
          <h3>Practices</h3>
          <p>Micro-interventions—movement, breath, ritual—scaled to real life.</p>
        </div>
        <div class='pillar'>
          <h3>Refinement</h3>
          <p>Adjustments based on outcomes and lived feedback, not guesswork.</p>
        </div>
      </div>

      <div class='pricing-comparator' aria-hidden='false'>
        <div class='comp-inner'>
          <div class='comp-toggle' role='tablist' aria-label='Billing toggle'>
            <button class='toggle-btn active' data-mode='monthly' role='tab' aria-selected='true'>Monthly</button>
            <button class='toggle-btn' data-mode='package' role='tab' aria-selected='false'>Package</button>
          </div>

          <div class='comp-cards'>
            <div class='card basic'>
              <h4>Foundation Path</h4>
              <div class='price' data-monthly='120' data-package='330' aria-live='polite'>$<span class='num'>120</span></div>
              <p class='muted'>Weekly touchpoints, plan + tools</p>
            </div>
            <div class='card focused'>
              <h4>Focused Path</h4>
              <div class='price' data-monthly='220' data-package='590'>$<span class='num'>220</span></div>
              <p class='muted'>Deeper measures, prioritized coaching</p>
            </div>
            <div class='card deep'>
              <h4>Intensive Path</h4>
              <div class='price' data-monthly='420' data-package='1100'>$<span class='num'>420</span></div>
              <p class='muted'>Comprehensive testing and weekly clinical contact</p>
            </div>
          </div>
        </div>
      </div>

    </section>

    <section class='case-notes wrap' aria-labelledby='case-title'>
      <h2 id='case-title'>Case notes & credibility</h2>
      <div class='case-grid'>
        <div class='proof-gallery' aria-live='polite'>
          <div class='testimonies' id='testimonies'>
            <blockquote class='quote active' data-author='A. S.'>
              "My sleep shifted in three weeks when we tuned the small daily anchors. The plan was human-scale and actually stuck."
            </blockquote>
            <blockquote class='quote' data-author='M. R.'>
              "I trusted the process: measured steps, quick feedback, and tools I could use when things felt hard."
            </blockquote>
            <blockquote class='quote' data-author='J. L.'>
              "They tied together tests, lifestyle, and culture. It felt like a map rather than a prescription."
            </blockquote>
          </div>
          <div class='gallery-controls'>
            <button id='prevTest' aria-label='Previous testimonial'>&larr;</button>
            <button id='nextTest' aria-label='Next testimonial'>&rarr;</button>
          </div>
        </div>

        <aside class='badges' aria-label='Credentials and badges'>
          <div class='badge' tabindex='0' data-tooltip='Clinician-led programs with licensed practitioners'>
            <svg width='36' height='36' viewBox='0 0 24 24' aria-hidden='true'><path d='M12 2 L15 8 L22 9 L17 14 L18 21 L12 18 L6 21 L7 14 L2 9 L9 8 Z' fill='currentColor'/></svg>
            <span>Licensed Clinicians</span>
          </div>
          <div class='badge' tabindex='0' data-tooltip='Programs informed by peer-reviewed research and practical tests'>
            <svg width='36' height='36' viewBox='0 0 24 24' aria-hidden='true'><circle cx='12' cy='12' r='9' fill='currentColor'/></svg>
            <span>Evidence-informed</span>
          </div>
          <div class='badge' tabindex='0' data-tooltip='Privacy-first data practices and client-centered consent'>
            <svg width='36' height='36' viewBox='0 0 24 24' aria-hidden='true'><rect x='4' y='4' width='16' height='16' fill='currentColor'/></svg>
            <span>Privacy-first</span>
          </div>
          <div class='badge' tabindex='0' data-tooltip='Client-reported progress metrics across multiple cohorts'>
            <svg width='36' height='36' viewBox='0 0 24 24' aria-hidden='true'><path d='M3 12 L10 5 L21 16' stroke='currentColor' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>
            <span>Reported outcomes</span>
          </div>
        </aside>
      </div>
    </section>

    <section class='faq wrap' aria-labelledby='faq-title'>
      <h2 id='faq-title'>Questions people often bring</h2>
      <div class='faq-grid'>
        <details>
          <summary>What can I expect in the first month?</summary>
          <p>We focus on small, measurable shifts and establish a baseline. Expect short check-ins and a practical set of tools you can use daily.</p>
        </details>
        <details>
          <summary>Do you guarantee a cure?</summary>
          <p>No. We offer educational guidance and personalized plans. Outcomes vary. If you have urgent medical needs, please contact local emergency services or your primary clinician.</p>
        </details>
        <details>
          <summary>How do you measure progress?</summary>
          <p>We combine self-reported trackers with targeted measures and observational checkpoints to refine recommendations over time.</p>
        </details>
      </div>
    </section>

    <section class='cta wrap'>
      <div class='cta-inner'>
        <h2>Ready to begin a step-by-step path?</h2>
        <p>If you'd like a short exploratory consult, we can identify which pathway suits your life and priorities.</p>
        <div class='cta-actions'>
          <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Start with a short consult</a>
          <a class='btn ghost' href='contact.html'>Ask a quick question</a>
        </div>

        <div class='pricing-comparator compact' aria-hidden='false'>
          <div class='comp-inner'>
            <div class='comp-toggle' role='tablist' aria-label='Billing toggle compact'>
              <button class='toggle-btn active' data-mode='monthly' role='tab' aria-selected='true'>Monthly</button>
              <button class='toggle-btn' data-mode='package' role='tab' aria-selected='false'>Package</button>
            </div>
            <div class='comp-cards compact-cards'>
              <div class='card small'>
                <h4>Intro</h4>
                <div class='price' data-monthly='80' data-package='220'>$<span class='num'>80</span></div>
              </div>
              <div class='card small'>
                <h4>Core</h4>
                <div class='price' data-monthly='180' data-package='480'>$<span class='num'>180</span></div>
              </div>
            </div>
          </div>
        </div>

      </div>
    </section>
  </main>

  <footer class='site-footer'>
    <div class='wrap footer-grid'>
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} · <a href='tel:{{PHONE}}'>{{PHONE}}</a>
      </div>
      <div class='footer-links'>
        <a href='services.html'>Programs</a>
        <a href='pricing.html'>Invest</a>
        <a href='contact.html'>Contact</a>
      </div>
      <div>
        <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a>
      </div>
    </div>
  </footer>

  <script src='assets/js/main.js' defer></script>
</body>
</html>"} 
