{"path":"assets/css/styles.css","content":"/* Core styles for the holistic / integrative medicine template */
:root{
  --bg:#fbfcfa; --muted:#6b6b6b; --accent:#477b6f; --accent-2:#7bb197; --glass: rgba(255,255,255,0.6);
  --max:1100px; --radius:12px; --card:#ffffff; --shadow:0 8px 24px rgba(21,30,23,0.06);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#102018;background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.header-grid{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:18px}
.brand{display:flex;align-items:center;gap:10px;color:var(--accent);text-decoration:none}
.brand .logo{color:var(--accent)}
.nav a{margin:0 10px;color:#0d1b18;text-decoration:none;font-weight:600}
.book-link{background:transparent;padding:8px 12px;border-radius:8px;border:1px solid rgba(70,120,110,0.08)}
.nav-cta .btn{margin-left:12px}
.btn{display:inline-block;padding:8px 14px;border-radius:10px;text-decoration:none;font-weight:700}
.btn.primary{background:linear-gradient(180deg,var(--accent),var(--accent-2));color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(16,32,24,0.06);color:#102018}
.btn.large{padding:14px 20px;font-size:1.05rem}
.page-hero .hero{padding-top:40px;padding-bottom:40px}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:30px;align-items:center}
.hero-copy .eyebrow{font-size:0.95rem;color:var(--accent);margin:0 0 6px}
.lead{font-size:1.08rem;line-height:1.5;color:#163425}
.hero-actions{margin-top:18px;display:flex;gap:12px}
.hero-stats{display:flex;gap:20px;margin-top:18px;list-style:none;padding:0}
.hero-stats li{font-size:0.9rem}
.pattern-plate{background:url('../assets/img/pattern.svg') center/cover no-repeat;border-radius:14px;height:260px;box-shadow:var(--shadow);}
.myth-truth{margin-top:26px;background:linear-gradient(180deg,#ffffff,#fbfffb);padding:26px;border-radius:12px}
.myth-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.myth-grid article{background:var(--card);padding:14px;border-radius:10px;box-shadow:var(--shadow)}
.pillars{margin-top:26px}
.pillars-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}
.pillar{background:var(--card);padding:14px;border-radius:12px;box-shadow:var(--shadow)}
.pricing-comparator{margin-top:18px;padding:16px;background:linear-gradient(180deg, #fff, #f8fdf8);border-radius:12px;box-shadow:var(--shadow)}
.comp-toggle{display:inline-flex;background:rgba(16,32,24,0.03);border-radius:12px;padding:4px}
.toggle-btn{border:0;background:transparent;padding:8px 12px;border-radius:10px;cursor:pointer}
.toggle-btn.active{background:#fff;box-shadow:0 6px 18px rgba(16,32,24,0.06);color:var(--accent)}
.comp-cards{display:flex;gap:10px;margin-top:12px}
.card{background:var(--card);padding:14px;border-radius:10px;flex:1;text-align:center}
.card h4{margin:0 0 6px}
.price{font-size:1.5rem;font-weight:800;color:var(--accent)}
.muted{color:var(--muted);font-size:0.95rem}
.case-notes{margin-top:26px}
.case-grid{display:grid;grid-template-columns:1fr 220px;gap:18px}
.proof-gallery{background:linear-gradient(180deg,#fff,#fbfcfb);padding:16px;border-radius:12px;box-shadow:var(--shadow)}
.testimonies{height:140px;position:relative;overflow:hidden}
.quote{position:absolute;opacity:0;transform:translateY(6px);transition:opacity .45s ease,transform .45s ease;padding:12px;font-size:1rem}
.quote.active{opacity:1;transform:none}
.gallery-controls{display:flex;gap:8px;margin-top:12px}
.gallery-controls button{background:var(--card);border:1px solid rgba(16,32,24,0.06);padding:8px;border-radius:8px;cursor:pointer}
.badges{display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.badge{display:flex;gap:10px;align-items:center;background:var(--card);padding:8px;border-radius:10px;cursor:pointer;box-shadow:var(--shadow);}
.badge svg{color:var(--accent)}
.badge span{font-weight:600}
.badge[data-tooltip]{position:relative}
.badge-tooltip{position:fixed;background:#102018;color:#fff;padding:8px 10px;border-radius:8px;font-size:0.9rem;box-shadow:0 8px 24px rgba(0,0,0,0.18);pointer-events:none;opacity:0;transform:translateY(6px);transition:opacity .18s ease,transform .18s ease}
.faq{margin-top:26px}
.faq-grid details{background:var(--card);padding:12px;border-radius:8px;margin-bottom:8px}
.cta{margin-top:26px;padding:22px;border-radius:14px;background:linear-gradient(180deg,#f9fffb,#fff)}
.cta-actions{display:flex;gap:12px;margin-top:12px}
.site-footer{border-top:1px solid rgba(16,32,24,0.04);margin-top:26px;background:transparent}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .pillars-grid{grid-template-columns:repeat(2,1fr)}
  .case-grid{grid-template-columns:1fr}
  .header-grid{grid-template-columns:1fr auto;}
}
@media (max-width:560px){
  .pillars-grid{grid-template-columns:1fr}
  .nav a{display:none}
}"} 
{"path":"assets/js/main.js","content":"(function(){
  // Proof Gallery: rotate testimonials and badges with tooltips
  var testiRoot = document.getElementById('testimonies');
  var quotes = testiRoot ? Array.from(testiRoot.querySelectorAll('.quote')) : [];
  var current = 0; var interval = 5000; var timer = null;
  function showQuote(i){
    quotes.forEach(function(q, idx){ q.classList.toggle('active', idx===i); });
  }
  function nextQuote(){ current = (current+1)%quotes.length; showQuote(current); }
  function prevQuote(){ current = (current-1+quotes.length)%quotes.length; showQuote(current); }
  if(quotes.length){ showQuote(0); timer = setInterval(nextQuote, interval); }
  var btnNext = document.getElementById('nextTest'); var btnPrev = document.getElementById('prevTest');
  if(btnNext){ btnNext.addEventListener('click', function(){ clearInterval(timer); nextQuote(); timer = setInterval(nextQuote, interval); }); }
  if(btnPrev){ btnPrev.addEventListener('click', function(){ clearInterval(timer); prevQuote(); timer = setInterval(nextQuote, interval); }); }

  // Badges: tooltip that follows focus/hover
  var badges = Array.from(document.querySelectorAll('.badge[data-tooltip]'));
  var tipEl = document.createElement('div'); tipEl.className='badge-tooltip'; document.body.appendChild(tipEl);
  function showTip(text, x, y){ tipEl.textContent = text; tipEl.style.left = (x+12)+'px'; tipEl.style.top = (y+12)+'px'; tipEl.style.opacity='1'; tipEl.style.transform='translateY(0)'; }
  function hideTip(){ tipEl.style.opacity='0'; tipEl.style.transform='translateY(6px)'; }
  badges.forEach(function(b){
    var text = b.getAttribute('data-tooltip');
    b.addEventListener('mouseenter', function(e){ showTip(text, e.pageX, e.pageY); });
    b.addEventListener('mousemove', function(e){ showTip(text, e.pageX, e.pageY); });
    b.addEventListener('mouseleave', hideTip);
    b.addEventListener('focus', function(e){ var r = b.getBoundingClientRect(); showTip(text, r.left + window.scrollX, r.top + window.scrollY); });
    b.addEventListener('blur', hideTip);
  });

  // Pricing Comparator: toggle monthly vs package with animated numbers
  function animateNumber(el, to){
    var start = Number(el.textContent.replace(/[^0-9]/g,'')) || 0; var end = Number(to);
    var duration = 600; var startTime = null;
    function step(ts){ if(!startTime) startTime = ts; var progress = Math.min((ts-startTime)/duration,1); var val = Math.round(start + (end-start)*progress); el.textContent = val; if(progress<1) requestAnimationFrame(step); }
    requestAnimationFrame(step);
  }
  function updateComparator(root, mode){
    var cards = root.querySelectorAll('.price');
    cards.forEach(function(card){ var numEl = card.querySelector('.num'); var target = card.getAttribute('data-'+mode); animateNumber(numEl, target); });
  }
  var compToggles = Array.from(document.querySelectorAll('.pricing-comparator'));
  compToggles.forEach(function(root){
    var toggles = root.querySelectorAll('.toggle-btn');
    toggles.forEach(function(btn){ btn.addEventListener('click', function(){ toggles.forEach(function(b){ b.classList.toggle('active', b===btn); b.setAttribute('aria-selected', b===btn); }); var mode = btn.getAttribute('data-mode'); updateComparator(root, mode); }); });
  });

  // Initialize compact comparators by reading initial mode
  document.querySelectorAll('.pricing-comparator').forEach(function(root){ var active = root.querySelector('.toggle-btn.active') || root.querySelector('.toggle-btn'); if(active){ updateComparator(root, active.getAttribute('data-mode')); } });

  // Accessibility: allow keyboard switching of toggles via arrow keys
  document.addEventListener('keydown', function(e){
    if(document.activeElement && document.activeElement.classList.contains('toggle-btn')){
      var btn = document.activeElement; var parent = btn.parentElement; var items = Array.from(parent.querySelectorAll('.toggle-btn')); var idx = items.indexOf(btn);
      if(e.key === 'ArrowRight' || e.key === 'ArrowDown'){ e.preventDefault(); var next = items[(idx+1)%items.length]; next.focus(); next.click(); }
      if(e.key === 'ArrowLeft' || e.key === 'ArrowUp'){ e.preventDefault(); var prev = items[(idx-1+items.length)%items.length]; prev.focus(); prev.click(); }
    }
  });
})();"} 
